<?php
require 'config.php'; require_role('passenger');
$route=$_GET['route']??'R1'; if(!in_array($route,['R1','R2'],true))$route='R1';
$st=$pdo->prepare("SELECT d.driver_id,p.current_stop,p.departure_hour,p.departure_period,CASE WHEN p.is_active=1 THEN 'Available' ELSE 'Not Available' END status FROM departures p JOIN drivers d ON d.id=p.driver_pk WHERE p.route_code=? AND p.is_active=1 AND d.is_archived=0 ORDER BY d.driver_id");$st->execute([$route]);$rows=$st->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="5"><title>TranSeat - Passenger</title><link rel="stylesheet" href="style.css"></head><body><header class="topbar"><div class="brand"><img src="assets/logo.jpg">Passenger Dashboard</div><nav class="nav"><a href="logout.php">Log Out</a></nav></header><main class="container"><section class="card"><h2>Welcome, Passenger!</h2><div class="field" style="max-width:260px"><label>Choose Specific Route</label><select id="itmRoutes" onchange="location='passenger.php?route='+this.value"><option <?=($route==='R1'?'selected':'')?>>R1</option><option <?=($route==='R2'?'selected':'')?>>R2</option></select></div></section><section class="card"><h2>Available Drivers — <?=e($route)?></h2><p class="small">This list refreshes every 5 seconds while drivers have Departure ON.</p><div class="table-wrap"><table id="tblAvailableDriver"><thead><tr><th>Driver ID</th><th>Destination</th><th>Departure Time</th><th>Status</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="4">No available drivers for this route.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['driver_id'])?></td><td><?=e($r['current_stop'])?></td><td><?=e($r['departure_hour'])?> <?=e($r['departure_period'])?></td><td><span class="badge available"><?=e($r['status'])?></span></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></body></html>